function validate([boxes, portsCount, maxBoxes, maxWeight]) {
  const limit = 100000;
  const ok = v => Number.isInteger(v) && v >= 1 && v <= limit;
  if (!ok(portsCount) || !ok(maxBoxes) || !ok(maxWeight)) return 'portsCount, maxBoxes and maxWeight are between 1 and 10^5.';
  if (!Array.isArray(boxes) || boxes.length < 1 || boxes.length > limit) return 'boxes needs 1 to 10^5 entries.';
  for (const box of boxes) {
    if (!Array.isArray(box) || box.length !== 2) return 'Each box is [port, weight].';
    if (!Number.isInteger(box[0]) || box[0] < 1 || box[0] > portsCount) return 'Each port is between 1 and portsCount.';
    if (!Number.isInteger(box[1]) || box[1] < 1 || box[1] > maxWeight) return 'Each weight is between 1 and maxWeight.';
  }
  return null;
}

