function boxDelivering(boxes, portsCount, maxBoxes, maxWeight) {
  const n = boxes.length;
  const weight = new Array(n + 1).fill(0);
  const changes = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    weight[i] = weight[i - 1] + boxes[i - 1][1];
    const switched = i >= 2 && boxes[i - 1][0] !== boxes[i - 2][0];
    changes[i] = changes[i - 1] + (switched ? 1 : 0);
  }

  const dp = new Array(n + 1).fill(0);
  const score = new Array(n + 1).fill(0);
  score[0] = dp[0] - changes[1];
  const deque = [0];
  let head = 0;

  for (let i = 1; i <= n; i++) {
    while (i - deque[head] > maxBoxes || weight[i] - weight[deque[head]] > maxWeight) {
      head++;
    }
    dp[i] = score[deque[head]] + changes[i] + 2;
    if (i === n) {
      break;
    }
    score[i] = dp[i] - changes[i + 1];
    while (deque.length > head && score[deque[deque.length - 1]] >= score[i]) {
      deque.pop();
    }
    deque.push(i);
  }
  return dp[n];
}

