function boxDelivering(boxes, portsCount, maxBoxes, maxWeight) {
  const n = boxes.length;
  const best = new Array(n + 1).fill(Infinity);
  best[n] = 0;
  for (let start = n - 1; start >= 0; start--) {
    for (let end = start + 1; end <= n && end - start <= maxBoxes; end++) {
      let load = 0, trips = 1, at = 0;
      for (let k = start; k < end; k++) {
        load += boxes[k][1];
        if (boxes[k][0] !== at) { trips++; at = boxes[k][0]; }
      }
      if (load > maxWeight) break;
      best[start] = Math.min(best[start], trips + best[end]);
    }
  }
  return best[0];
}

