function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = pick(1500, 2000);
    const portsCount = [3, 20, 100000][pick(0, 2)];
    const maxBoxes = [1, pick(2, 50), pick(50, 2000), 100000][pick(0, 3)];
    const maxWeight = [pick(1, 100), pick(100, 10000), 100000][pick(0, 2)];
    const stay = rand();
    const boxes = [];
    let port = pick(1, portsCount);
    for (let i = 0; i < n; i++) {
      if (rand() >= stay) port = pick(1, portsCount);
      boxes.push([port, pick(1, Math.min(maxWeight, pick(1, 3) === 1 ? maxWeight : Math.max(1, Math.floor(maxWeight / 8))))]);
    }
    return [boxes, portsCount, maxBoxes, maxWeight];
  }
  const n = pick(1, 8);
  const portsCount = pick(1, 4);
  const maxBoxes = pick(1, n + 1);
  const maxWeight = pick(1, 10);
  const boxes = [];
  let port = pick(1, portsCount);
  for (let i = 0; i < n; i++) {
    if (rand() < 0.6) port = pick(1, portsCount);
    boxes.push([port, pick(1, maxWeight)]);
  }
  return [boxes, portsCount, maxBoxes, maxWeight];
}
